package com.openggf.game.soniccd.level;
import com.openggf.game.soniccd.player.*;
import com.openggf.game.soniccd.resources.CdPlayerArtRuntime;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
/** Tests FIRST; Java UNRUN. Authenticated original data + CONSTRUCTED complete component ingress.
 * No native boot/carry, actor hydration, Module/FULL/World or ordinary R3 gameplay admission. */
class TestCdR31aPlayerFrameEntry {
 private static final Runnable NOTHING=()->{};
 @Test void explicitFactoryBorrowsItsActualSourceWithoutAnyImplicitInitServiceOrClear()throws Exception{var a=actual();var s=state(0,0x42,0);var e=environment(0x100,1,0,0,0x34);var art=art();var clock=clock();try(var f=CdPlayerFrameRuntime.fromR31aEntry(a,s,e,art,clock)){assertTrue(f.stageSource().ownsR31aAssets(a));assertEquals(0x100,f.stageSource().ordinaryZoneActWord());assertEquals(1,f.stageSource().ordinaryPeriod());assertSame(a.sonic(),f.stageSource().sonic());assertSame(a.terrain(),f.stageSource().terrain());assertSame(s,f.state());assertSame(e,f.environment());assertSame(art,f.artState());assertSame(clock,f.vIntClock());assertTrue(f.display().isEmpty());assertFalse(f.paused());assertFalse(f.closed());assertThrows(IllegalStateException.class,()->f.runBody(1));assertEquals(0,s.motion().routine());assertEquals(0xA7,f.state().rotationDistance());assertEquals(0xB8,f.state().rotationAngle());}}
 @Test void exact0100PresentGateRejectsTruncatedOtherZoneAndMarkedPeriodsAtIngress()throws Exception{var a=actual();for(int act:new int[]{0,1,2,0x101,0x200,0x300,65535})assertEquals(CdPlayerFrameRuntime.UnsupportedBoundary.SOURCE_FAMILY,assertThrows(CdPlayerFrameRuntime.UnsupportedFrame.class,()->CdPlayerFrameRuntime.fromR31aEntry(a,state(0,0,0),environment(act,1,0,0,0),art(),clock())).boundary());for(int period:new int[]{0,2,0x80,0x81,0x82,255})assertEquals(CdPlayerFrameRuntime.UnsupportedBoundary.SOURCE_FAMILY,assertThrows(CdPlayerFrameRuntime.UnsupportedFrame.class,()->CdPlayerFrameRuntime.fromR31aEntry(a,state(0,0,0),environment(0x100,period,0,0,0),art(),clock())).boundary());}
 @Test void genuineServicedInitAdoptsOnlyOriginalResultAndLeavesArtClockDisplayUntouchedByBody()throws Exception{var a=actual();try(var f=CdPlayerFrameRuntime.fromR31aEntry(a,state(0,0x42,0),environment(0x100,1,0,0,0x34),art(),clock())){int[] uploads={0};f.bindArtPublication((request,complete)->{uploads[0]++;assertEquals(0xF000,request.vramByteAddress());assertSame(complete,f.artState());});var sample=f.prepareInput(0xF5);f.serviceVBlank(sample.phase(),NOTHING,NOTHING,NOTHING);assertEquals(1,uploads[0]);assertEquals(0,f.vIntClock().absoluteValue().orElseThrow());int word=f.advanceLevelMainFrame();assertEquals(0,word);var state=f.state();var environment=f.environment();var current=f.artState();var clock=f.vIntClock();var p=f.runBody(word);assertEquals(CdPlayerBody.Boundary.INIT_RETURN,p.result().boundary());assertSame(p.result().state(),f.state());assertSame(p.result().environment(),f.environment());TestCdR31aPlayerBodyInit.assertInit(state,environment,p.result(),false);assertSame(current,f.artState());assertSame(clock,f.vIntClock());assertTrue(p.sounds().isEmpty());assertTrue(p.result().display().isEmpty());assertTrue(f.display().isEmpty());assertThrows(IllegalStateException.class,()->f.runBody(word));}}
 @Test void nextMainConsumesOnlyTheRealEntitlementAndStopsBeforeAnyUnownedR3Prefix()throws Exception{try(var f=CdPlayerFrameRuntime.fromR31aEntry(actual(),state(0,0x42,0),environment(0x100,1,0,0,0),art(),clock())){f.runBody(service(f,0));int word=service(f,8);var state=f.state();var environment=f.environment();var art=f.artState();var clock=f.vIntClock();var error=assertThrows(CdPlayerBody.UnsupportedBody.class,()->f.runBody(word));assertEquals(CdPlayerBody.UnsupportedBoundary.R3_CONTINUATION_OWNER,error.boundary());assertSame(state,f.state());assertSame(environment,f.environment());assertSame(art,f.artState());assertSame(clock,f.vIntClock());assertFalse(f.closed());assertThrows(IllegalStateException.class,()->f.runBody(word));}}
 @Test void constructedHurtHasTheSamePreciseNoPublicationFence()throws Exception{try(var f=CdPlayerFrameRuntime.fromR31aEntry(actual(),state(4,0x42,0x20),environment(0x100,1,0,0,0),art(),clock())){int word=service(f,0);var before=f.state();var env=f.environment();var error=assertThrows(CdPlayerBody.UnsupportedBody.class,()->f.runBody(word));assertEquals(CdPlayerBody.UnsupportedBoundary.R3_CONTINUATION_OWNER,error.boundary());assertSame(before,f.state());assertSame(env,f.environment());assertTrue(f.display().isEmpty());assertFalse(f.closed());}}
 @Test void sameValueForeignFrameCapturesCannotRetargetThisSourceOrMintItsOwner()throws Exception{var actual=TestCdR31aPlayerCoreAssets.actual();var s=state(0,0x42,0);var e=environment(0x100,1,0,0,0);var art=art();var clock=clock();try(var a=CdPlayerFrameRuntime.fromR31aEntry(actual.first(),s,e,art,clock);var b=CdPlayerFrameRuntime.fromR31aEntry(actual.second(),s,e,art,clock);var same=CdPlayerFrameRuntime.fromR31aEntry(actual.first(),s,e,art,clock)){assertEquals(a.state(),b.state());assertEquals(a.environment(),b.environment());assertNotSame(a.stageSource(),b.stageSource());assertNotSame(a.captureActor().owner(),b.captureActor().owner());assertNotSame(a.captureActor().owner(),same.captureActor().owner());assertThrows(IllegalArgumentException.class,()->a.restoreActor(b.captureActor()));assertThrows(IllegalArgumentException.class,()->a.restoreShared(b.captureShared()));assertThrows(IllegalArgumentException.class,()->a.restoreActor(same.captureActor()));assertSame(s,a.state());assertSame(e,a.environment());assertTrue(a.stageSource().ownsR31aAssets(actual.first()));assertFalse(a.stageSource().ownsR31aAssets(actual.second()));}}
 @Test void ownCaptureBeforeInitRestoresAndReplaysThroughActualServiceWithoutExtraDefaults()throws Exception{try(var f=CdPlayerFrameRuntime.fromR31aEntry(actual(),state(0,0x42,0),environment(0x100,1,0,0,0),art(),clock())){int[] uploads={0};f.bindArtPublication((r,c)->uploads[0]++);var actor=f.captureActor();var shared=f.captureShared();int n=serviceBound(f,8);var first=f.runBody(n);var completeActor=f.captureActor();var completeShared=f.captureShared();f.restoreActor(actor);f.restoreShared(shared);assertEquals(0,f.state().motion().routine());var again=f.runBody(serviceBound(f,8));assertEquals(first.result(),again.result());assertEquals(completeActor,f.captureActor());assertSharedValue(completeShared,f.captureShared());assertEquals(2,uploads[0]);}}
 @Test void originalVintCallbackFaultRetainsReadPrefixWithoutInitOrAClockTick()throws Exception{try(var f=CdPlayerFrameRuntime.fromR31aEntry(actual(),state(0,0x42,0),environment(0x100,1,0,0,0),art(),clock())){f.bindArtPublication((r,c)->{});var before=f.state();var art=f.artState();var clock=f.vIntClock();var original=new AssertionError("Original publication port");var sample=f.prepareInput(8);assertSame(original,assertThrows(AssertionError.class,()->f.serviceVBlank(sample.phase(),()->{throw original;},NOTHING,NOTHING)));assertSame(before,f.state());assertSame(art,f.artState());assertSame(clock,f.vIntClock());assertEquals(8,f.environment().controls().rawHeld());assertTrue(f.closed());assertThrows(IllegalStateException.class,()->f.runBody(1));}}
 @Test void r31CannotUseRetainedPpzExitApisAndPpzCannotUseTheNewRawWord()throws Exception{try(var f=CdPlayerFrameRuntime.fromR31aEntry(actual(),state(0,0x42,0),environment(0x100,1,0,0,0),art(),clock())){var shared=f.captureShared();assertEquals(CdPlayerFrameRuntime.UnsupportedBoundary.SOURCE_FAMILY,assertThrows(CdPlayerFrameRuntime.UnsupportedFrame.class,()->f.serviceOldProgrammeExitLoad(0,f.state(),f.environment(),NOTHING,NOTHING,NOTHING)).boundary());assertEquals(shared,f.captureShared());}var r13=TestCdR13PlaneSources.actual().getFirst();try(var f=CdPlayerFrameRuntime.fromAct3FutureEntry(r13,state(0,0x42,0),environment(0x100,1,0,0,0),art(),clock())){assertEquals(CdPlayerFrameRuntime.UnsupportedBoundary.SOURCE_FAMILY,assertThrows(CdPlayerFrameRuntime.UnsupportedFrame.class,()->f.serviceLevelLoad(0,NOTHING,NOTHING,NOTHING)).boundary());assertFalse(f.closed());}}
 @Test void missingCompleteValuesRejectWithoutChoosingAnyPlayerArtOrClockDefault()throws Exception{assertThrows(NullPointerException.class,()->CdPlayerFrameRuntime.fromR31aEntry(null,state(0,0,0),environment(0x100,1,0,0,0),art(),clock()));var a=actual();assertThrows(NullPointerException.class,()->CdPlayerFrameRuntime.fromR31aEntry(a,null,environment(0x100,1,0,0,0),art(),clock()));assertThrows(NullPointerException.class,()->CdPlayerFrameRuntime.fromR31aEntry(a,state(0,0,0),null,art(),clock()));assertThrows(NullPointerException.class,()->CdPlayerFrameRuntime.fromR31aEntry(a,state(0,0,0),environment(0x100,1,0,0,0),null,clock()));assertThrows(NullPointerException.class,()->CdPlayerFrameRuntime.fromR31aEntry(a,state(0,0,0),environment(0x100,1,0,0,0),art(),null));}
 @Test void oneNewFiniteFactoryKeepsCaptureAndConstructorShapesExact()throws Exception{var m=CdPlayerFrameRuntime.class.getDeclaredMethod("fromR31aEntry",CdR31aAssets.class,CdPlayerBody.State.class,CdPlayerBody.Environment.class,CdPlayerArtRuntime.State.class,CdPlayerFrameRuntime.VIntClock.class);assertTrue(java.lang.reflect.Modifier.isPublic(m.getModifiers()));assertTrue(java.lang.reflect.Modifier.isStatic(m.getModifiers()));assertEquals(CdPlayerFrameRuntime.class,m.getReturnType());assertEquals(List.of(java.io.IOException.class),Arrays.asList(m.getExceptionTypes()));assertEquals(1,Arrays.stream(CdPlayerFrameRuntime.class.getDeclaredMethods()).filter(v->v.getName().equals("fromR31aEntry")).count());assertEquals(2,CdPlayerFrameRuntime.class.getDeclaredConstructors().length);assertEquals(3,CdPlayerFrameRuntime.ActorState.class.getRecordComponents().length);assertEquals(5,CdPlayerFrameRuntime.SharedState.class.getRecordComponents().length);assertEquals(8,CdPlayerBody.State.class.getRecordComponents().length);assertEquals(21,CdPlayerBody.UnsupportedBoundary.LEVEL_MUSIC_GOOD_FUTURE.ordinal());assertEquals(22,CdPlayerBody.UnsupportedBoundary.R3_CONTINUATION_OWNER.ordinal());assertEquals(23,CdPlayerBody.UnsupportedBoundary.values().length);}
 static void assertSharedValue(CdPlayerFrameRuntime.SharedState expected,CdPlayerFrameRuntime.SharedState actual){assertSame(expected.owner(),actual.owner());assertEquals(expected.environment(),actual.environment());assertEquals(expected.paused(),actual.paused());assertEquals(expected.vIntClock(),actual.vIntClock());assertArrayEquals(expected.artState().cpuBuffer().copy(),actual.artState().cpuBuffer().copy());assertArrayEquals(expected.artState().residentBank().copy(),actual.artState().residentBank().copy());assertEquals(expected.artState().lastFrame(),actual.artState().lastFrame());assertEquals(expected.artState().dirty(),actual.artState().dirty());}
 static CdR31aAssets actual()throws Exception{return TestCdR31aPlayerCoreAssets.actual().first();}
 static int service(CdPlayerFrameRuntime f,int held){f.bindArtPublication((r,c)->{});return serviceBound(f,held);}
 static int serviceBound(CdPlayerFrameRuntime f,int held){var selected=f.prepareInput(held);f.serviceVBlank(selected.phase(),NOTHING,NOTHING,NOTHING);return f.advanceLevelMainFrame();}
 static CdPlayerBody.State state(int routine,int flags,int charge){return state(routine,flags,charge,0x10);}
 static CdPlayerBody.State state(int routine,int flags,int charge,int control){byte[] history=new byte[256];for(int i=0;i<history.length;i++)history[i]=(byte)(13*i+7);return new CdPlayerBody.State(new CdPlayerMotionState(0x01234567,0x023489AB,-0x123,0x234,-0x345,routine,0x56,flags,0x23,7,11,6,7,9,charge,-0x1234,0x44,control,0x77,0x88),new CdPlayerBody.AnimationCursor(5,6,0x43),new CdPlayerBody.Header(1,0x12345678,0x2345,3,0x21),new CdPlayerBody.Timers(0x1234,0x2345,0x3456,0x4567),new CdPlayerBody.History(CdAssetBytes.copyOf(history),0xFFF1),0xA7,new CdPlayerBody.ObjectLinks(0x20,0x7F),0xB8);}
 static CdPlayerBody.Environment environment(int act,int period,int mini,int attack,int debug){return new CdPlayerBody.Environment(new CdPlayerMovement.Environment(new CdPlayerMovement.Physics(0x123,0x23,0x34),new CdPlayerMovement.Bounds(0x12,0x2345,0x3456,0x78),new CdPlayerMovement.Gates(act,period,mini,0x34,0x56,0x78,255),new CdPlayerMovement.Globals(0x12,0x2345,0x34,0x56,65535,0x4567,0x78,0x89,0x9A,0xAB)),new CdPlayerBody.Controls(0x24,0x18,8,0x10,0x81),new CdPlayerBody.Globals(65535,0x2345,attack,debug,0x4567,0xFFFE,0x56,0x78),CdPlayerBody.DynamicSlots.UNIMPLEMENTED);}
 static CdPlayerArtRuntime.State art(){byte[] cpu=new byte[768],resident=new byte[768];for(int i=0;i<768;i++){cpu[i]=(byte)(7*i+3);resident[i]=(byte)(11*i+5);}return new CdPlayerArtRuntime.State(cpu,resident,0xA1,true);}
 static CdPlayerFrameRuntime.VIntClock clock(){return new CdPlayerFrameRuntime.VIntClock(OptionalLong.of(0xFFFF_FFFEL),1);}
}
